static int inet_guard(s32 protocol) { if (protocol < 0 || protocol >= IPPROTO_MAX) return 1; return 0; }
static int fam_guard(s32 protocol)  { if (protocol < 0 || protocol > SK_PROTOCOL_MAX) return 1; return 0; }
int main(void) {
